//! The fading curve: one slow breath, 1024 steps from dark up to full and back
//! down (a raised cosine), then 128 steps resting at the bottom. The table is
//! generated by `build.rs` from the formula.

include!(concat!(env!("OUT_DIR"), "/curve.rs"));

/// Length of the whole cycle in steps (the breath plus the rest).
pub const LEN: u16 = CURVE.len() as u16;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn shape() {
        assert_eq!(CURVE.len(), 1152);
        assert_eq!(CURVE[0], 0);
        // the top of the breath is half way through the 1024 steps
        assert!(CURVE[512] >= 65534);
        // rises monotonically to the top, falls back
        for n in 1..=512 {
            assert!(CURVE[n] >= CURVE[n - 1], "not rising at {n}");
        }
        for n in 513..1024 {
            assert!(CURVE[n] <= CURVE[n - 1], "not falling at {n}");
        }
        // the rest at the bottom
        assert!(CURVE[1024..].iter().all(|&v| v == 0));
    }

    #[test]
    fn matches_formula() {
        for (n, &v) in CURVE[..1024].iter().enumerate() {
            let a = 2.0 * core::f64::consts::PI * n as f64 / 1024.0 + 1.5 * core::f64::consts::PI;
            let want = ((libm_sin(a) + 1.0) * 32768.0) as i64;
            assert!((v as i64 - want.clamp(0, 65535)).abs() <= 1, "step {n}");
        }
    }

    fn libm_sin(x: f64) -> f64 {
        std::primitive::f64::sin(x)
    }
}
